//! 🖼️ Blueprint and Preview borrow shared Drawing composition and publish one funded Canvas fragment per original turn.
use super::*;
use semio_framework_job::{StepContext,OriginalTurnFailure};
use semio_framework_value::{RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind};
use semio_s_artifact_layout_layout_engine::scene::drawing_planning::{DrawingSourceAddress,DrawingPlacement,DrawingPaint,composition::{DrawingCompositionTurn,canvas}};
#[derive(Clone,Copy)]
pub(super) enum LiveDrawingPiece{Path{index:usize},Glyph{label:usize,glyph:usize,paint:DrawingPaint,affine:[f64;6]},Image{rect:[f64;4],affine:[f64;6]}}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"layout live Drawing publication is invalid")}
fn reserve(chunks:&mut List<Chunk>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if chunks.has_reserved_slot(){return Ok(true);}let demand=RetirementDemand{copy_bytes:chunks.next_reserve_copy_byte_demand()?,capacity_bytes:chunks.next_allocation_bytes()?,depth:chunks.next_reserve_depth_demand()?,..Default::default()};let g=cx.retained_grant();if g.maximum_items==0||g.maximum_copy_bytes<demand.copy_bytes||g.maximum_capacity_bytes<demand.capacity_bytes||g.maximum_depth<demand.depth{return Ok(false);}let result=chunks.reserve_one_funded(g);match result{Ok(progress)=>cx.consume_retained(progress)?,Err(error)=>{cx.consume_retained(RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,..Default::default()})?;return Err(ValueError::from(error.refusal()).into());}}cx.consume_fuel(1);Ok(false)}
fn copy(chunks:&mut List<Chunk>,total:&mut usize,text:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !reserve(chunks,cx)?{return Ok(false);}let g=cx.retained_grant();let bytes=std::mem::size_of::<Chunk>().checked_add(text.len()).ok_or_else(invalid)?;if g.maximum_items==0||g.maximum_copy_bytes<bytes||g.maximum_capacity_bytes<text.len()||g.maximum_depth<1{return Ok(false);}let end=text.len();let next=total.checked_add(end).ok_or_else(invalid)?;let mut value=String::new();value.try_reserve_exact(end).map_err(|_|invalid())?;let capacity=value.capacity();value.push_str(text);chunks.push_reserved(Chunk{value,start:0,end}).map_err(|_|invalid())?;*total=next;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
fn move_image(chunks:&mut List<Chunk>,total:&mut usize,image:&mut String,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !reserve(chunks,cx)?{return Ok(false);}let g=cx.retained_grant();if g.maximum_items==0||g.maximum_copy_bytes<std::mem::size_of::<Chunk>()||g.maximum_depth<1{return Ok(false);}let end=image.len();let next=total.checked_add(end).ok_or_else(invalid)?;chunks.push_reserved(Chunk{value:std::mem::take(image),start:0,end}).map_err(|_|invalid())?;*total=next;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<Chunk>(),..Default::default()})?;cx.consume_fuel(1);Ok(true)}
impl LayoutRenderWork{
 pub(super) fn advance_drawing(&mut self,snapshot:&LayoutSnapshot,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if snapshot as*const LayoutSnapshot as usize!=self.source{return Err(invalid().into());}let document=self.owners.preview.as_ref().unwrap_or(snapshot);
  if self.phase==11{
   if self.owners.drawing.has_active(){let g=cx.retained_grant();let result=self.owners.drawing.advance(document,semio_framework_io_ports::VectorSceneGrant{maximum_source_items:g.maximum_items,maximum_copy_bytes:g.maximum_copy_bytes,maximum_capacity_bytes:g.maximum_capacity_bytes,maximum_release_bytes:g.maximum_release_bytes,maximum_depth:g.maximum_depth});let p=self.owners.drawing.last_receipt();cx.consume_retained(RetainedCloneProgress{copied_items:p.source_items,copied_bytes:p.copied_bytes,retained_capacity_bytes:p.retained_capacity_bytes,released_bytes:p.released_bytes})?;self.drawing_demand=self.owners.drawing.next_demand(document,512)?;let turn=result.map_err(semio_framework_plugin::Fault::from)?;match turn{DrawingCompositionTurn::Progress=>{},DrawingCompositionTurn::Done=>self.phase=self.drawing_resume,DrawingCompositionTurn::Path{index}=>{self.drawing_piece=Some(LiveDrawingPiece::Path{index});self.drawing_segment=0;self.phase=12;},DrawingCompositionTurn::Glyph{label,glyph,paint,affine}=>{self.drawing_piece=Some(LiveDrawingPiece::Glyph{label,glyph,paint,affine});self.drawing_segment=0;self.phase=12;},DrawingCompositionTurn::Image{x,y,width,height,affine,proxy}=>{self.owners.drawing_image=proxy;self.drawing_piece=Some(LiveDrawingPiece::Image{rect:[x,y,width,height],affine});self.phase=15;}}cx.consume_fuel(1);return Ok(false);}
   let Some(page_index)=self.drawing_page else{self.phase=3;return Ok(false);};let page=document.pages.get(page_index).ok_or_else(invalid)?;let present=match self.drawing_background{0=>document.background_drawing.is_some(),1=>page.background_drawing.is_some(),_=>{self.phase=3;return Ok(false);}};let source=if self.drawing_background==0{DrawingSourceAddress::Document}else{DrawingSourceAddress::Page(page_index)};let placement=if self.drawing_background==0{DrawingPlacement::Content}else{DrawingPlacement::Canvas};self.drawing_background+=1;if present{self.owners.drawing.begin(source,placement,semio_s_artifact_layout_layout_model::LayoutBounds{x:0.0,y:0.0,width:page.width,height:page.height,rotation:0.0}).map_err(semio_framework_plugin::Fault::from)?;self.drawing_demand=self.owners.drawing.next_demand(document,512)?;self.drawing_resume=11;}cx.consume_fuel(1);return Ok(false);
  }
  if self.phase==16{if move_image(&mut self.owners.chunks,&mut self.bytes,&mut self.owners.drawing_image,cx)?{self.phase=17;}return Ok(false);}
  if self.phase==17{if copy(&mut self.owners.chunks,&mut self.bytes,canvas::IMAGE_END,cx)?{self.finish_drawing_piece();}return Ok(false);}
  let Some(fragment)=self.drawing_fragment()?else{self.phase=14;return Ok(false);};let text=fragment.as_str();let start=self.drawing_fragment_byte;let take=(text.len()-start).min(512).min(cx.retained_grant().maximum_copy_bytes.saturating_sub(std::mem::size_of::<Chunk>()));if take==0{return Ok(false);}if copy(&mut self.owners.chunks,&mut self.bytes,&text[start..start+take],cx)?{self.drawing_fragment_byte+=take;if self.drawing_fragment_byte==text.len(){self.drawing_fragment_byte=0;match self.phase{12=>self.phase=13,13=>self.drawing_segment+=1,14=>self.finish_drawing_piece(),15=>self.phase=16,_=>return Err(invalid().into())}}}Ok(false)
 }
 fn drawing_fragment(&self)->Result<Option<canvas::CanvasFragment>,ValueError>{let piece=self.drawing_piece.ok_or_else(invalid)?;match self.phase{
  12=>{let affine=match piece{LiveDrawingPiece::Path{index}=>self.owners.drawing.path(index).map_err(|_|invalid())?.info.affine,LiveDrawingPiece::Glyph{affine,..}=>affine,_=>return Err(invalid())};canvas::path_start(self.drawing_id,affine).map(Some).map_err(|_|invalid())},
  13=>{let segment=match piece{LiveDrawingPiece::Path{index}=>self.owners.drawing.path(index).map_err(|_|invalid())?.segments.get(self.drawing_segment),LiveDrawingPiece::Glyph{label,glyph,..}=>self.owners.drawing.segment(label,glyph,self.drawing_segment).map_err(|_|invalid())?,_=>return Err(invalid())};segment.map(|value|canvas::segment(value,self.drawing_segment>0).map_err(|_|invalid())).transpose()},
  14=>{let paint=match piece{LiveDrawingPiece::Path{index}=>self.owners.drawing.path(index).map_err(|_|invalid())?.info.paint,LiveDrawingPiece::Glyph{paint,..}=>paint,_=>return Err(invalid())};canvas::path_end(paint).map(Some).map_err(|_|invalid())},
  15=>{let LiveDrawingPiece::Image{rect,affine}=piece else{return Err(invalid());};canvas::image_start(self.drawing_id,affine,rect).map(Some).map_err(|_|invalid())},
  _=>Err(invalid())}}
 pub(super) fn drawing_publication_demand(&self,maximum_body_bytes:usize)->Result<RetirementDemand,ValueError>{let one=RetirementDemand{depth:1,..Default::default()};if self.phase==11{return Ok(self.drawing_demand);}if !self.owners.chunks.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:self.owners.chunks.next_reserve_copy_byte_demand()?,capacity_bytes:self.owners.chunks.next_allocation_bytes()?,depth:self.owners.chunks.next_reserve_depth_demand()?,..Default::default()});}if self.phase==16{return Ok(RetirementDemand{copy_bytes:std::mem::size_of::<Chunk>(),..one});}let bytes=if self.phase==17{canvas::IMAGE_END.len()}else{let Some(fragment)=self.drawing_fragment()?else{return Ok(one);};(fragment.as_str().len()-self.drawing_fragment_byte).min(512).min(maximum_body_bytes.saturating_sub(std::mem::size_of::<Chunk>()).max(1))};Ok(RetirementDemand{copy_bytes:std::mem::size_of::<Chunk>()+bytes,capacity_bytes:bytes,..one})}

 fn finish_drawing_piece(&mut self){self.drawing_fragment_byte=0;self.drawing_piece=None;self.drawing_segment=0;self.drawing_id+=1;self.phase=11;}
}
